```json
{
  "root_causes": [
    {
      "service": "rate",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT count(*) n, approx_quantile(c.duration,0.5)/1e6 client_p50_ms, approx_quantile(s.duration,0.5)/1e6 server_p50_ms, approx_quantile(c.duration - s.duration,0.5)/1e6 gap_p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='search' AND c.span_name='rate.Rate/GetRates' AND s.service_name='rate'",
          "claim": "search's rate.Rate/GetRates client spans take about 1.5 s, while rate's server spans stay under 2 ms, so the gap is on the wire."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE span_name='rate.Rate/GetRates' GROUP BY 1,2,3 UNION ALL SELECT service_name, span_name, attr_span_kind, count(*), approx_quantile(duration,0.95)/1e6 FROM normal_traces WHERE span_name='rate.Rate/GetRates' GROUP BY 1,2,3",
          "claim": "rate's own GetRates server p95 is about 1.3 ms in both periods; the slowdown is only in the caller's client span from search."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='search' AND span_name IN ('geo.Geo/Nearby','rate.Rate/GetRates') GROUP BY 1,2",
          "claim": "Search's geo.Geo/Nearby calls stay around 0.6 ms while its rate.Rate/GetRates calls take about 1.6 s, so only the search→rate connection is slow."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "rate",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='search' AND span_name IN ('search.Search/Nearby','rate.Rate/GetRates') GROUP BY 1,2",
          "claim": "search.Search/Nearby p95 rises to about 1.6 s in step with its slow rate.Rate/GetRates calls (normal about 2 ms)."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('HTTP /hotels','search.Search/Nearby') GROUP BY 1,2,3",
          "claim": "frontend's HTTP /hotels and its search.Search/Nearby client spans both reach about 1.6 s p95, versus about 7 ms and 2.7 ms before."
        }
      ]
    }
  ]
}
```

